// === Tab: mySketch ===
let theShader;

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
}

function draw() {
  shader(theShader);

  // Enviamos la resolución PERO intercambiamos ancho/alto porque vamos a rotar
  theShader.setUniform("u_resolution", [height, width]);
  theShader.setUniform("u_time", millis() / 3000.0);
  theShader.setUniform("u_frame", frameCount);
  theShader.setUniform("u_mouse", [
    (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / 100.0,
    map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, height, 0) / 100.0
  ]);

  // --- ROTACIÓN COMPLETA DEL CANVAS (90 grados) ---
  rotateZ(HALF_PI);

  // Dibujamos un quad gigante para garantizar calidad completa
  rectMode(CENTER);
  rect(0, 0, max(width, height), max(width, height));
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}


// === Tab: frag ===
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;

// --- 基础 hash + noise ---
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// --- fbm（多层 noise） ---
float fbm(vec2 p) {
    float value = 0.0;
    float amplitude = 0.25;
    for (int i = 0; i < 2; i++) {
        value += amplitude * noise(p);
        p *= 1.25;
        amplitude *= 0.125;
    }
    return value;
}

// --- 等高线细线函数 ---
float contourLines(float v, float frequency, float line_thickness) {
    float lines = abs(fract(v * frequency) - 0.299);
    return smoothstep(0.5 - line_thickness, 0.499 + line_thickness, lines);
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_resolution.xy;
    uv = uv * -4.0 - 10.0;
    uv.x *= u_resolution.x / u_resolution.y;

    // --- 流动扭曲 warp ---
    vec2 warp1 = vec2(
        noise(uv * 1.0 + vec2(u_time * 1.3, u_time * 0.2)),
        noise(uv * 120.0 + vec2(-u_time * 0.4, u_time * 0.2))
    );
    vec2 uv2 = uv + (warp1 - 0.25) * 0.6;

    vec2 warp2 = vec2(
        noise(uv2 * 1.0 + vec2(-u_time * 0.6, u_time * 0.4)),
        noise(uv2 * 190.0 + vec2(u_time * 2.5, u_time * 0.3))
    );
    vec2 uvFinal = uv2 + (warp2 - 1.5) / 0.995;

    // --- fbm flow ---
    vec2 flow = uvFinal + vec2(u_time * 0.26, u_time * 0.1);
    float n = fbm(flow);

    // --- 边缘检测（可选） ---
    float n1 = fbm(flow + vec2(0.001, 0.0));
    float n2 = fbm(flow + vec2(0.0, 0.001));
    float grad = length(vec2(n1 - n, n2 - n));
    float edge = smoothstep(0.02, 0.2, grad);

    // --- 等高线细线生成 ---
    float frequency = sin(u_time*0.1) * 10.0 + 10.0;
    float thickness = 0.125;
    float lines = contourLines(n, frequency, thickness);

    float finalVal = mix(lines, 1.0, edge * 0.9);

    // ------------------------------
    // PALETA EN AZULES Y CELESTES
    // ------------------------------
    vec3 darkBlue   = vec3(0.04, 0.02, 0.20);
    vec3 midBlue    = vec3(0.05, 0.30, 0.80);
    vec3 lightBlue  = vec3(0.40, 0.75, 1.00);

    vec3 baseColor = mix(darkBlue, midBlue, finalVal);
    baseColor = mix(baseColor, lightBlue, edge * 0.6);

    gl_FragColor = vec4(baseColor, 1.0);
}
`;


// === Tab: vert ===


const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

